(()=>{const LOGO='data:image/webp;base64,';const GUIDE='data:image/webp;base64,';function apply(){document.querySelectorAll('img[alt="GOS Fulfilment"]').forEach(img=>img.src=LOGO);const guide=document.querySelector('.tutorial-guide');if(guide)guide.src=GUIDE;}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply,{once:true});else apply();})();